{
  "iteration": 3,
  "pcvs": [
    {
      "name": "request_tokens",
      "expression": "request.num_tokens",
      "rationale": "Retains eight distinct observed prompt-length states and models the baseline length dependence."
    },
    {
      "name": "ten_token_prompt",
      "expression": "int(request.num_tokens == 10)",
      "rationale": "Separates the observed ten-token state, whose instruction cost was substantially above baseline."
    },
    {
      "name": "eleven_token_prompt",
      "expression": "int(request.num_tokens == 11)",
      "rationale": "Separates the other observed high-cost short-prompt state."
    }
  ],
  "hypothesis": "The fixed workload has approximately constant empty-search cost except for the ten- and eleven-token observations. These indicators test that empirical distinction; prompt length may be a proxy for initialization effects rather than their cause."
}
